# owner: platform
"""Round spans to a fixed step and label them."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

def _check_step(step: int) -> None:
    if not isinstance(step, int) or step <= 0 or 60 % step:
        raise ValueError(f"bad step: {step!r}")

def _round_minutes(minutes: int, step: int) -> int:
    """Nearest multiple of step, with halfway going up."""
    return (minutes + step // 2) // step * step

def _round_span(span: Span, step: int) -> Span:
    start = _round_minutes(span.start, step)
    end = _round_minutes(span.end, step)
    if start >= end:
        text = format_span(span)
        raise ValueError(f"{text} is empty after rounding")
    return Span(start, end)

def _label(span: Span) -> str:
    hours, minutes = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {minutes}m)"

# ---
def round_span_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Round each span to the step and label it.

    A label is the rounded span and its length.
    Steps must divide 60 evenly, or ValueError is raised.
    """
    _check_step(step)
    rounded = (_round_span(span, step) for span in spans)
    return [_label(span) for span in rounded]
